fn admit_recursive_member_set(
    app: &mut VcsArtifactApp<ComposedParentApp, RecursiveTestMembers>,
    handle: crate::app::ArtifactEnvelopeDecodeOperationHandle,
    row: &Value,
    ingress: Vec<crate::app::OwnedDocumentMemberIngress>,
) {
