struct RecursiveBranchSnapshot {
    #[state(artifact)]
    count: i32,
    #[state(artifact)]
    label: String,
    #[state(artifact)]
    #[child(kind = "s.test.child")]
    nested: Option<RecursiveFixtureChild>,
